test('invoiceTotals applies bulk discount for 10+ units', () => {
  const invoice = {
    lines: [{ sku: 'SKU-001', qty: 10, unitPrice: 1000, vatRate: 0, discountPercent: 0 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 10000);
  const bulkDiscount = Math.round(10000 * 2.5 / 100);
  assert.equal(r.value.discount, bulkDiscount);
  assert.equal(r.value.total, 10000 - bulkDiscount);
});

test('invoiceTotals no bulk discount for 9 units', () => {
  const invoice = {
    lines: [{ sku: 'SKU-001', qty: 9, unitPrice: 1000, vatRate: 0, discountPercent: 0 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 9000);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.total, 9000);
});

test('invoiceTotals bulk discount applied after line discount', () => {
  const invoice = {
    lines: [{ sku: 'SKU-001', qty: 10, unitPrice: 1000, vatRate: 0, discountPercent: 10 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 10000);
  const lineDiscount = 10000 * 0.1;
  const afterLineDiscount = 10000 - lineDiscount;
  const bulkDiscount = Math.round(afterLineDiscount * 2.5 / 100);
  assert.equal(r.value.discount, 1000 + bulkDiscount);
  assert.equal(r.value.total, 10000 - 1000 - bulkDiscount);
});

