    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 2, unitPrice: 8500, vatRate: 0, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 3, unitPrice: 9500, vatRate: 0, discountPercent: 20 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  const line1Total = 2 * 8500;
  const line1Discount = 1700;
  const line2Total = 3 * 9500;
  const line2Discount = 5700;
  assert.equal(r.value.subtotal, line1Total + line2Total);
  assert.equal(r.value.discount, line1Discount + line2Discount);
  assert.equal(r.value.vat, 0);
  assert.equal(r.value.total, line1Total + line2Total - line1Discount - line2Discount);
});

