test('invoiceTotals with voucher calculation', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 }],
    voucher: { code: 'SUMMER2026', amount: 5000 },
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 100000);
  const bulkDiscount = Math.round(100000 * 2.5 / 100);
  const afterBulk = 100000 - bulkDiscount;
  const vat = Math.round(afterBulk * 21 / 100);
  assert.equal(r.value.discount, bulkDiscount);
  assert.equal(r.value.vat, vat);
  assert.equal(r.value.voucher, 5000);
  assert.equal(r.value.total, 100000 - bulkDiscount + vat - 5000);
});

test('invoiceTotals with voucher and discount', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 10 }],
    voucher: { code: 'SUMMER2026', amount: 5000 },
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 100000);
  assert.equal(r.value.discount, 10000);
  const vat = Math.round((100000 - 10000) * 21 / 100);
  assert.equal(r.value.vat, vat);
  assert.equal(r.value.voucher, 5000);
  assert.equal(r.value.total, 100000 - 10000 + vat - 5000);
});

